html:
{% set company_currency = frappe.db.get_value("Company", doc.company, "default_currency") %}
{% set company_addr = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") %}
{% set company_address = frappe.get_doc("Address", company_addr) if company_addr else None %}
{% set show_dual_currency = doc.currency != company_currency %}

{%- set qr_text = "Quotation: " ~ doc.name ~ " | Customer: " ~ (doc.customer_name or doc.party_name) ~ " | Date: " ~ doc.transaction_date | string ~ " | Total: " ~ doc.grand_total | string ~ " " ~ doc.currency %}
{%- set _ns = namespace(qr_b64=None) %}
{%- if get_doc_qr_code is defined and get_doc_qr_code is callable %}
  {%- set _ns.qr_b64 = get_doc_qr_code(doc.doctype, doc.name) %}
{%- elif frappe.utils.get_qr_code is defined and frappe.utils.get_qr_code is callable %}
  {%- set _ns.qr_b64 = frappe.utils.get_qr_code(qr_text) %}
{%- endif %}

<style>
  * { box-sizing: border-box; }
  .cgm-root { font-family: Arial, sans-serif; color: #171717; font-size: 10.5px; position: relative; }
  .cgm-header { width: 100%; border-collapse: collapse; margin-bottom: 6px; }
  .cgm-header-letter { width: 58%; vertical-align: middle; padding-right: 16px; }
  .cgm-header-letter .letter-head { margin: 0; padding: 0; line-height: 1.35; }
  .cgm-header-letter .letter-head > div { text-align: left !important; width: auto !important; }
  .cgm-header-letter .letter-head p { margin: 0 0 2px; }
  .cgm-header-letter .letter-head h3 { margin: 2px 0; font-size: 11px; }
  .cgm-header-letter .letter-head img {
    display: block;
    width: auto !important;
    height: auto !important;
    max-width: 200px !important;
    max-height: 52px !important;
    object-fit: contain;
  }
  .cgm-header-meta { width: 42%; vertical-align: middle; text-align: right; padding-top: 0; }
  .cgm-doc-title { font-size: 18px; font-weight: 900; letter-spacing: 1.2px; color: #171717; margin: 0 0 4px; text-transform: uppercase; }
  .cgm-doc-meta-tbl { border-collapse: collapse; margin-left: auto; }
  .cgm-doc-meta-tbl td { padding: 1px 0; font-size: 10px; }
  .cgm-doc-meta-tbl .lbl { color: #888; font-weight: 600; white-space: nowrap; padding-right: 8px; text-align: left; }
  .cgm-doc-meta-tbl .val { font-weight: 700; color: #171717; text-align: right; white-space: nowrap; }
  .cgm-divider { border: none; border-top: 2px solid #c41e3a; margin: 6px 0 10px; }
  .cgm-addr-tbl { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
  .cgm-addr-tbl td { vertical-align: top; width: 50%; padding: 6px 12px 6px 0; }
  .cgm-addr-tbl td:first-child { border-right: 1px solid #e8e8e8; padding-left: 0; }
  .addr-type { font-size: 9px; font-weight: 700; color: #c41e3a; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 4px; }
  .company-name { font-weight: 700; font-size: 11.5px; margin-bottom: 3px; }
  .addr-line { font-size: 10px; color: #444; line-height: 1.6; }
  .cgm-ship-tbl { width: 100%; border-collapse: collapse; margin-bottom: 14px; background: #fafafa; border: 0.5px solid #e8e8e8; }
  .cgm-ship-tbl td { padding: 7px 12px; width: 33.33%; vertical-align: top; border-right: 0.5px solid #efefef; }
  .cgm-ship-tbl td:last-child { border-right: none; }
  .cgm-ship-tbl tr:first-child td { border-bottom: 0.5px solid #efefef; }
  .sh-label { font-size: 8.5px; color: #888; text-transform: uppercase; letter-spacing: 0.8px; margin-bottom: 3px; }
  .sh-value { font-weight: 700; font-size: 11px; color: #171717; }
  .cgm-section-head { display: table; width: 100%; margin: 14px 0 8px; }
  .sec-bar { display: table-cell; width: 4px; background: #c41e3a; border-radius: 2px; }
  .sec-title { display: table-cell; padding: 0 10px; font-size: 10px; font-weight: 800; color: #8b1a1a; text-transform: uppercase; letter-spacing: 1.2px; white-space: nowrap; vertical-align: middle; }
  .sec-line { display: table-cell; width: 100%; border-top: 1px solid #e8e8e8; vertical-align: middle; }
  .cgm-table { width: 100%; border-collapse: collapse; font-size: 10.5px; }
  .cgm-table thead tr th { padding: 7px 9px; font-size: 9px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.8px; border-bottom: 2px solid #6b1010; background: #8b1a1a; color: #fff; }
  .cgm-table thead tr th.sub-currency { background: #6b1010; font-weight: 400; opacity: 0.9; }
  .cgm-table tbody tr td { padding: 6px 9px; border-bottom: 0.5px solid #f0f0f0; vertical-align: middle; }
  .cgm-table tbody tr:last-child td { border-bottom: none; }
  .cgm-table tbody tr:nth-child(even) td { background: #fafafa; }
  .cgm-table .num { text-align: right; white-space: nowrap; font-variant-numeric: tabular-nums; }
  .cgm-table .col-divider { border-left: 1px solid #e8e8e8; }
  .cgm-totals-block { margin-top: 16px; border: 0.5px solid #e0e0e0; border-radius: 8px; overflow: hidden; }
  .cgm-totals-block table { width: 100%; border-collapse: collapse; }
  .cgm-totals-block td { padding: 6px 14px; }
  .cgm-totals-block tr { border-bottom: 0.5px solid #f0f0f0; }
  .cgm-totals-block tr:last-child { border-bottom: none; }
  .cgm-totals-block .tot-label { color: #666; text-align: right; font-size: 10px; }
  .cgm-totals-block .tot-val { text-align: right; font-weight: 600; font-size: 11px; white-space: nowrap; min-width: 130px; }
  .cgm-totals-block .grand-row td { background: #f4f4f4; color: #171717; }
  .cgm-totals-block .grand-row .tot-label { color: #171717; font-weight: 700; font-size: 11px; }
  .cgm-totals-block .grand-row .tot-val { color: #171717; font-size: 14px; font-weight: 800; }
  .cgm-totals-block .grand-row-alt td { background: #8b1a1a; color: #fff !important; }
  .cgm-totals-block .grand-row-alt .tot-label { color: rgba(255,255,255,0.85); font-weight: 600; font-size: 10.5px; }
  .cgm-totals-block .grand-row-alt .tot-val { color: #fff; font-size: 12.5px; font-weight: 700; }
  .cgm-in-words { margin-top: 10px; padding: 8px 12px; background: #f9f9f9; border-left: 3px solid #c41e3a; font-style: italic; font-size: 10px; color: #444; border-radius: 0 4px 4px 0; }
  .cgm-in-words + .cgm-in-words { margin-top: 6px; }
  .cgm-terms { margin-top: 16px; border: 0.5px solid #e8c8c8; border-radius: 6px; padding: 12px 14px; background: #fdf5f5; font-size: 9.5px; color: #444; line-height: 1.7; }
  .cgm-terms .terms-head { font-weight: 700; font-size: 10px; color: #8b1a1a; margin-bottom: 6px; text-transform: uppercase; letter-spacing: 1px; }
  .cgm-fx-note { margin-top: 8px; font-size: 9px; color: #888; text-align: right; font-style: italic; }
  .cgm-footer-tbl { width: 100%; border-collapse: collapse; margin-top: 20px; border-top: 0.5px solid #e0e0e0; padding-top: 12px; }
  .cgm-footer-tbl td { vertical-align: bottom; padding-top: 12px; }
  .footer-note { font-size: 8.5px; color: #888; line-height: 1.6; }
  .cgm-qr-wrap { text-align: center; width: 100px; margin-left: auto; }
  .cgm-qr-wrap img { display: block; width: 100px; height: 100px; object-fit: contain; }
  .cgm-qr-wrap .qr-label { font-size: 8px; color: #888; text-transform: uppercase; letter-spacing: 1px; margin-top: 4px; }
</style>

<div class="cgm-root">

  <table class="cgm-header">
    <tr>
      <td class="cgm-header-letter">
        {% if not no_letterhead and letter_head %}
        <div class="letter-head">{{ letter_head }}</div>
        {% endif %}
      </td>
      <td class="cgm-header-meta">
        <div class="cgm-doc-title">Quotation</div>
        <table class="cgm-doc-meta-tbl">
          <tr>
            <td class="lbl">Date</td>
            <td class="val">{{ frappe.utils.format_date(doc.transaction_date) }}</td>
          </tr>
          <tr>
            <td class="lbl">Quotation No.</td>
            <td class="val">{{ doc.name }}</td>
          </tr>
          {% if doc.valid_till %}
          <tr>
            <td class="lbl">Valid Till</td>
            <td class="val">{{ frappe.utils.format_date(doc.valid_till) }}</td>
          </tr>
          {% endif %}
          {% if doc.custom_our_ref_no %}
          <tr>
            <td class="lbl">Our Ref</td>
            <td class="val">{{ doc.custom_our_ref_no }}</td>
          </tr>
          {% endif %}
          {% if doc.custom_client_ref_no %}
          <tr>
            <td class="lbl">Client Ref</td>
            <td class="val">{{ doc.custom_client_ref_no }}</td>
          </tr>
          {% endif %}
        </table>
      </td>
    </tr>
  </table>

  <hr class="cgm-divider">

  <table class="cgm-addr-tbl">
    <tr>
      <td>
        <div class="addr-type">From</div>
        <div class="company-name">{{ doc.company }}</div>
        {% if company_address %}
          {% if company_address.address_line1 %}<div class="addr-line">{{ company_address.address_line1 }}</div>{% endif %}
          {% if company_address.address_line2 %}<div class="addr-line">{{ company_address.address_line2 }}</div>{% endif %}
          <div class="addr-line">{{ company_address.city or "" }}{% if company_address.country %}, {{ company_address.country }}{% endif %}</div>
        {% endif %}
      </td>
      <td style="padding-left:20px;">
        <div class="addr-type">To</div>
        <div class="company-name">{{ doc.customer_name or doc.party_name }}</div>
        <div class="addr-line">{{ doc.address_display or "" }}</div>
      </td>
    </tr>
  </table>

  <table class="cgm-ship-tbl">
    <tr>
      <td>
        <div class="sh-label">HS Code</div>
        <div class="sh-value">{{ doc.custom_hs_code or "—" }}</div>
      </td>
      <td>
        <div class="sh-label">Commodity</div>
        <div class="sh-value">{{ doc.custom_commodity or "—" }}</div>
      </td>
      <td>
        <div class="sh-label">Total Weight (Tons)</div>
        <div class="sh-value">{{ doc.custom_weight or "—" }}</div>
      </td>
    </tr>
    <tr>
      <td>
        <div class="sh-label">FCL / Container</div>
        <div class="sh-value">{{ doc.custom_quantity or doc.custom_container_size or "" }} {{ doc.custom_container_type or "—" }}</div>
      </td>
      <td>
        <div class="sh-label">Port of Loading</div>
        <div class="sh-value">{{ doc.custom_port_of_loading or "—" }}</div>
      </td>
      <td>
        <div class="sh-label">Port of Discharge</div>
        <div class="sh-value">{{ doc.custom_port_of_discharge or "—" }}</div>
      </td>
    </tr>
    {% if doc.custom_shipment or doc.incoterm %}
    <tr>
      <td>
        <div class="sh-label">Shipment / Project</div>
        <div class="sh-value">{{ doc.custom_shipment or "—" }}</div>
      </td>
      <td>
        <div class="sh-label">Incoterm</div>
        <div class="sh-value">{{ doc.incoterm or "—" }}{% if doc.named_place %} ({{ doc.named_place }}){% endif %}</div>
      </td>
      <td>
        <div class="sh-label">Shipment Type</div>
        <div class="sh-value">{{ doc.custom_shipment_type or "—" }}</div>
      </td>
    </tr>
    {% endif %}
  </table>

  <div class="cgm-section-head">
    <div class="sec-bar"></div>
    <div class="sec-title">Local Charges</div>
    <div class="sec-line"></div>
  </div>

  <table class="cgm-table">
    <thead>
      <tr>
        <th style="width:{{ '34%' if show_dual_currency else '50%' }}">Description</th>
        <th class="num" style="width:8%">Qty</th>
        <th class="num" style="width:{{ '13%' if show_dual_currency else '15%' }}">Unit Price <span style="font-weight:400;opacity:.8;">({{ doc.currency }})</span></th>
        <th class="num" style="width:{{ '13%' if show_dual_currency else '15%' }}">Amount <span style="font-weight:400;opacity:.8;">({{ doc.currency }})</span></th>
      <!--  {% if show_dual_currency %}-->
      <!--  <th class="num sub-currency col-divider" style="width:12%">Unit Price ({{ company_currency }})</th>-->
      <!--  <th class="num sub-currency" style="width:12%">Amount ({{ company_currency }})</th>-->
      <!--  {% endif %}-->
      <!--</tr>-->
    </thead>
    <tbody>
      {% for item in doc.items %}
      <tr>
        <td>{{ item.description or item.item_name }}</td>
        <td class="num">{{ item.qty }}</td>
        <td class="num">{{ item.get_formatted("rate", doc) }}</td>
        <td class="num">{{ item.get_formatted("amount", doc) }}</td>
        <!--{% if show_dual_currency %}-->
        <!--<td class="num col-divider">{{ frappe.utils.fmt_money(item.base_rate, currency=company_currency) }}</td>-->
        <!--<td class="num">{{ frappe.utils.fmt_money(item.base_amount, currency=company_currency) }}</td>-->
        <!--{% endif %}-->
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <div class="cgm-totals-block">
    <table>
      <tr>
        <td class="tot-label">Sub Total Local Charges ({{ doc.currency }})</td>
        <td class="tot-val">{{ doc.get_formatted("total") }}</td>
      </tr>
      {% if show_dual_currency %}
      <tr>
        <td class="tot-label">Sub Total Local Charges ({{ company_currency }})</td>
        <td class="tot-val">{{ frappe.utils.fmt_money(doc.base_total, currency=company_currency) }}</td>
      </tr>
      {% endif %}

      {% for tax in doc.taxes or [] %}
        {% if tax.tax_amount %}
        <tr>
          <td class="tot-label">{{ tax.description }} ({{ doc.currency }})</td>
          <td class="tot-val">{{ tax.get_formatted("tax_amount") }}</td>
        </tr>
        {% if show_dual_currency %}
        <tr>
          <td class="tot-label">{{ tax.description }} ({{ company_currency }})</td>
          <td class="tot-val">{{ frappe.utils.fmt_money(tax.base_tax_amount, currency=company_currency) }}</td>
        </tr>
        {% endif %}
        {% endif %}
      {% endfor %}

      <tr class="grand-row">
        <td class="tot-label">Grand Total ({{ doc.currency }})</td>
        <td class="tot-val">{{ doc.get_formatted("grand_total") }}</td>
      </tr>
      {% if show_dual_currency %}
      <tr class="grand-row-alt">
        <td class="tot-label">Grand Total ({{ company_currency }})</td>
        <td class="tot-val">{{ frappe.utils.fmt_money(doc.base_grand_total, currency=company_currency) }}</td>
      </tr>
      {% endif %}
    </table>
  </div>

  {% if show_dual_currency %}
  <div class="cgm-fx-note">
    Exchange Rate: 1 {{ doc.currency }} = {{ "%.2f"|format(doc.conversion_rate) }} {{ company_currency }}
  </div>
  {% endif %}

  {% if doc.in_words %}
  <div class="cgm-in-words">
    <strong>In Words ({{ doc.currency }}):</strong> {{ doc.in_words }}
  </div>
  {% endif %}
  {% if show_dual_currency and doc.base_in_words %}
  <div class="cgm-in-words">
    <strong>In Words ({{ company_currency }}):</strong> {{ doc.base_in_words }}
  </div>
  {% endif %}

  {% if doc.custom_quote_clause or doc.terms %}
  <div class="cgm-terms">
    <div class="terms-head">Remarks &amp; Terms</div>
    {{ doc.custom_quote_clause or "" }}
    {% if doc.terms %}<br>{{ doc.terms }}{% endif %}
  </div>
  {% endif %}

  <table class="cgm-footer-tbl">
    <tr>
      <td>
        <div class="footer-note">
          Document prepared by <strong>{{ doc.company }}</strong> &nbsp;|&nbsp; {{ frappe.utils.format_date(doc.transaction_date) }}<br>
          Quotation valid until {{ frappe.utils.format_date(doc.valid_till) if doc.valid_till else "further notice" }}.
        </div>
      </td>
      <td style="text-align:right;">
        <div class="cgm-qr-wrap">
          {% if _ns.qr_b64 %}
            <img src="data:image/png;base64,{{ _ns.qr_b64 }}" width="100" height="100" alt="Scan to verify">
          {% endif %}
          <div class="qr-label">Scan to verify</div>
        </div>
      </td>
    </tr>
  </table>

</div>

{% if not no_letterhead and footer %}
<div class="letter-head-footer">{{ footer }}</div>
{% endif %}
